const settleDeviceRevocation = `-- name: SettleDeviceRevocation :one
UPDATE device_inventory_cache
SET revocation_state       = $1,
    revocation_verified_at = CASE WHEN $1::text = 'applied' THEN now() ELSE NULL END,
    expiry                 = CASE WHEN $2::boolean THEN $3::timestamptz ELSE expiry END,
    online                 = CASE WHEN $4::boolean THEN false ELSE online END,
    removed_at             = CASE WHEN $4::boolean THEN COALESCE(removed_at, now()) ELSE removed_at END
WHERE tenant_id = $5 AND id = $6 AND revocation_state = 'pending'
  AND revocation_job_id = $7
RETURNING id, tenant_id, instance_id, headscale_node_id, machine_key, node_key, name, given_name, ip_addresses, headscale_user_id, owner_membership_id, tags, register_method, online, last_seen, expiry, approved_routes, available_routes, subnet_routes, hs_created_at, first_seen_at, last_synced_at, sync_generation, removed_at, enrollment_request_id, revocation_state, revocation_kind, revocation_requested_at, revocation_verified_at, revocation_job_id
`

